{"command":"cat <<'PYEOF' | python3 -
import json, subprocess, sys, textwrap, os
pod = {"apiVersion":"v1","kind":"Pod","metadata":{"name":"probe-api","namespace":"default"},"spec":{
  "restartPolicy":"Never",
  "containers":[{"name":"c","image":"busybox:1.37.0","command":["sh","-c"],"args":[
    textwrap.dedent("""
      set -- $(getent hosts kubernetes.default.svc $(ls /etc/resolv.conf | awk '{print $2}')); echo "svc resolved=$*"; echo "node=$(hostname -I)";
      for ip in $*; do echo "== $ip:6443:"; wget -q -S --header "Authorization: Bearer $(cat /var/run/secrets/kubernetes.io/serviceaccount/token)" https://$ip/api | head -6; done;
      for i in 1 2 3; do wget -q -O - --header "Authorization: Bearer $(cat /var/run/secrets/kubernetes.io/serviceaccount/token)" https://$ip/api/v1/namespaces/default/configmaps; head -4; echo "---"; sleep 5; done
    """).split()}]} };
print(json.dumps(pod, indent=2))
PYEOF"}

